package com.mooncast.host;
import java.util.*;
public final class PanelRecoveryJournalTest {
 static int checks;static void check(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}
 static final class Disk implements PanelRecoveryJournal.Storage {Map<String,Boolean> disk=new HashMap<>();boolean fail;public boolean read(String k){return disk.getOrDefault(k,false);}public boolean write(String k,boolean v){if(fail)return false;disk.put(k,v);return true;}}
 public static void main(String[] args){Disk d=new Disk();PanelRecoveryJournal j=new PanelRecoveryJournal(d);check(!j.blocked()&&j.arm(),"OFF allowed only after durable arm");check(new PanelRecoveryJournal(d).blocked(),"process death before recovery quarantines restarted owner");check(j.restored()&&!new PanelRecoveryJournal(d).blocked(),"ordered successful ON can retire clean arm");check(j.arm(),"normal next manual OFF");d.fail=true;j.quarantine();check(j.blocked()&&new PanelRecoveryJournal(d).blocked(),"failed permanent quarantine write retains durable armed fallback");check(!j.restored()&&!j.arm(),"visible acknowledgement cannot clear quarantine or replace helper");d=new Disk();d.fail=true;j=new PanelRecoveryJournal(d);check(!j.arm()&&j.blocked(),"failed initial durable write refuses physical OFF");d=new Disk();j=new PanelRecoveryJournal(d);check(j.arm(),"clear failure setup");d.fail=true;check(!j.restored()&&new PanelRecoveryJournal(d).blocked(),"failed clean-marker write fails closed across restart");System.out.println("PASS panel recovery durable journal: "+checks+" checks; no physical device claim");}
}
